import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
    selector: 'app-contact',
    standalone: true,
    imports: [CommonModule],
    template: `
    <section id="contact" class="contact-section">
      <div class="container">
        <h2 class="section-title">Get In Touch</h2>
        <div class="contact-card fade-in">
          <div class="contact-info">
            <h3>Let's Talk</h3>
            <p>I'm currently opening to new opportunities. Whether you have a question or just want to say hi, I'll try my best to get back to you!</p>
            
            <div class="info-item">
              <strong>Email:</strong>
              <a href="mailto:contact@zakaria.dev">contact@zakaria.dev</a>
            </div>
            
            <div class="social-links">
              <a href="#" class="social-icon">Li</a> <!-- Placeholder for icon -->
              <a href="#" class="social-icon">Gh</a>
            </div>
          </div>
          
          <form class="contact-form" (submit)="onSubmit($event)">
            <div class="form-group">
              <label for="name">Name</label>
              <input type="text" id="name" placeholder="John Doe" required>
            </div>
            
            <div class="form-group">
              <label for="email">Email</label>
              <input type="email" id="email" placeholder="john@example.com" required>
            </div>
            
            <div class="form-group">
              <label for="message">Message</label>
              <textarea id="message" rows="5" placeholder="Your message here..." required></textarea>
            </div>
            
            <button type="submit" class="btn btn-primary full-width">Send Message</button>
          </form>
        </div>
      </div>
    </section>
  `,
    styles: [`
    .contact-section { background-color: var(--card-bg); }
    .section-title { text-align: center; margin-bottom: 3rem; font-size: 2.5rem; color: var(--primary-color); }
    
    .contact-card {
      background: var(--bg-color);
      border-radius: 2rem;
      padding: 3rem;
      box-shadow: 0 10px 40px rgba(0,0,0,0.08);
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 3rem;
      max-width: 900px;
      margin: 0 auto;

      @media(max-width: 768px) {
        grid-template-columns: 1fr;
        padding: 2rem;
      }
    }

    .contact-info {
      h3 { font-size: 2rem; margin-bottom: 1rem; color: var(--text-color); }
      p { margin-bottom: 2rem; color: var(--text-color); opacity: 0.8; }
      
      .info-item {
        margin-bottom: 1.5rem;
        strong { display: block; color: var(--secondary-color); margin-bottom: 0.2rem; }
        a { color: var(--text-color); text-decoration: none; font-size: 1.1rem; &:hover { color: var(--primary-color); } }
      }
    }

    .social-links {
      display: flex;
      gap: 1rem;
      margin-top: 2rem;
      
      .social-icon {
        width: 40px;
        height: 40px;
        background: var(--card-bg);
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        color: var(--primary-color);
        font-weight: bold;
        text-decoration: none;
        transition: 0.3s;
        
        &:hover {
          background: var(--primary-color);
          color: white;
          transform: translateY(-3px);
        }
      }
    }

    .form-group {
      margin-bottom: 1.5rem;
      
      label { display: block; margin-bottom: 0.5rem; font-weight: 500; font-size: 0.9rem; }
      
      input, textarea {
        width: 100%;
        padding: 0.8rem 1rem;
        border: 2px solid var(--card-bg);
        background: var(--card-bg);
        border-radius: 0.5rem;
        font-family: inherit;
        color: var(--text-color);
        transition: 0.3s;
        
        &:focus {
          outline: none;
          border-color: var(--primary-color);
          background: var(--bg-color);
        }
      }
    }

    .full-width { width: 100%; }
  `]
})
export class ContactComponent {
    onSubmit(event: Event) {
        event.preventDefault();
        alert('Thank you for reaching out! This is a demo form.');
    }
}
